00020      void Mesh::Draw(Shader& shader)
00021     {
00022         unsigned int diffuseNr = 1;
00023         unsigned int specularNr = 1;
00024         for (unsigned int i = 0; i < textures.size(); i++)
00025         {
00026             glActiveTexture(GL_TEXTURE0 + i); // activate texture unit first
00027             // retrieve texture number (the N in diffuse_textureN)
00028             string number;
00029             string name = textures[i].type;
00030             if (name == "texture_diffuse")
00031                 number = std::to_string(diffuseNr++);
00032             else if (name == "texture_specular")
00033                 number = std::to_string(specularNr++);
00034                 shader.setFloat(("material" + name + number).c_str(), i);
00035             glBindTexture(GL_TEXTURE_2D, textures[i].id);
00036         }
00037         glActiveTexture(GL_TEXTURE0);
00038         // draw mesh
00039 //      glBindFramebuffer(GL_FRAMEBUFFER, PAIN::Render::FBO);
00040 
00041         glBindVertexArray(VAO);
00042         glDrawElements(GL_TRIANGLES, indices.size(), GL_UNSIGNED_INT, 0);
00043         glBindVertexArray(0);
00044     //  glBindFramebuffer(GL_FRAMEBUFFER, 0);
00045 
00046     }
