00048      void Mesh::Draw(ShaderU& shader)
00049     {
00050         unsigned int diffuseNr = 1;
00051         unsigned int specularNr = 1;
00052         for (unsigned int i = 0; i < textures.size(); i++)
00053         {
00054             glActiveTexture(GL_TEXTURE0 + i); // activate texture unit first
00055             // retrieve texture number (the N in diffuse_textureN)
