00072      void Mesh::setupMesh()
00073     {
00074         glGenVertexArrays(1, &VAO);
00075         glGenBuffers(1, &VBO);
00076         glGenBuffers(1, &EBO);
00077         glBindVertexArray(VAO);
00078         glBindBuffer(GL_ARRAY_BUFFER, VBO);
00079         glBufferData(GL_ARRAY_BUFFER, vertices.size() * sizeof(Vertex),
00080             &vertices[0], GL_STATIC_DRAW);
00081         glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, EBO);
00082         glBufferData(GL_ELEMENT_ARRAY_BUFFER, indices.size() *
00083             sizeof(unsigned int), &indices[0], GL_STATIC_DRAW);
00084         // vertex positions
00085         glEnableVertexAttribArray(0);
00086         glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex),
00087             (void*)0);
00088         // vertex normals
00089         glEnableVertexAttribArray(1);
00090         glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex),
00091             (void*)offsetof(Vertex, Normal));
00092         // vertex texture coords
00093         glEnableVertexAttribArray(2);
00094         glVertexAttribPointer(2, 2, GL_FLOAT, GL_FALSE, sizeof(Vertex),
00095             (void*)offsetof(Vertex, TexCoords));
00096         glBindVertexArray(0);
00097     }
