00121      void Model::loadModel(string path)
00122     {
00123         TracyCZoneN(ctux, "loading", true);
00124         Assimp::Importer import;
00125 
00126         const aiScene * scene = import.ReadFile(path, aiProcess_Triangulate |
00127             aiProcess_FlipUVs);
00128         if (!scene || scene->mFlags & AI_SCENE_FLAGS_INCOMPLETE ||
00129             !scene->mRootNode)
00130         {
00131             cout << "ERROR::ASSIMP::" << import.GetErrorString() << endl;
00132             TracyCZoneEnd(ctux);
00133 
00134             return;
00135         }
00136         directory = path.substr(0, path.find_last_of('\\'));
00137         processNode(scene->mRootNode, scene);
00138         TracyCZoneEnd(ctux);
00139 
00140     }
