00142      void Model::processNode(aiNode* node, const aiScene* scene)
00143     {
00144         //TrPr(ctx, __func__)
00145         // process all the node’s meshes (if any)
00146         for (unsigned int i = 0; i < node->mNumMeshes; i++)
00147         {
00148             aiMesh* mesh = scene->mMeshes[node->mMeshes[i]];
00149             meshes.push_back(processMesh(mesh, scene));
00150         }
00151         // then do the same for each of its children
00152         for (unsigned int i = 0; i < node->mNumChildren; i++)
00153         {
00154             processNode(node->mChildren[i], scene);
00155         }
00156         //TrPrE(ctx);
00157     }
