00159      Mesh Model::processMesh(aiMesh* mesh, const aiScene* scene)
00160     {
00161         //TrPr(ctx, __func__)
00162         //ZoneNamed(procces_mesh, true);
00163         vector<Vertex> vertices;
00164         vertices.reserve(mesh->mNumVertices);
00165         vector<unsigned int> indices;
00166         vector<Texture> textures;
00167         Vertex vertex;
00168 
00169         for (unsigned int i = 0; i < mesh->mNumVertices; i++)
00170         {
00171             //ZoneNamed(gather_verts, true);
00172 
00173             // process vertex positions, normals and texture coordinates
00174             //[...]
00175             //DATATYPES::TS_P_Vector3 vector;
00176             //vector = mesh->mVertices[i];
00177 
00178             vertex.Position = mesh->mVertices[i];
00179             //vector.x = mesh->mVertices[i].x;
00180             //vector.y = mesh->mVertices[i].y;
00181             //vector.z = mesh->mVertices[i].z;
00182             //vertex.Position = vector;
00183             //vector = mesh->mNormals[i];
00184             //vector.x = mesh->mNormals[i].x;
00185             //vector.y = mesh->mNormals[i].y;
00186             //vector.z = mesh->mNormals[i].z;
00187             vertex.Normal = mesh->mNormals[i];
00188             if (mesh->mTextureCoords[0]) // does the mesh contain texture coordinates?
00189             {
00190                 glm::vec2 vec;
00191                 vec.x = mesh->mTextureCoords[0][i].x;
00192                 vec.y = mesh->mTextureCoords[0][i].y;
00193                 vertex.TexCoords = vec;
00194             }
00195             else
00196             {
00197                 vertex.TexCoords = glm::vec2(0.0f, 0.0f);
00198             }
00199             vertices.push_back(vertex);
00200         }
00201         vertices.shrink_to_fit();
00202         // process indices
00203         //[...]
00204         indices.reserve(mesh->mNumFaces);
00205         for (unsigned int i = 0; i < mesh->mNumFaces; i++)
00206         {
00207 
00208 
00209             //aiFace face = mesh->mFaces[i];
00210             for (unsigned int j = 0; j < mesh->mFaces[i].mNumIndices; j++) {
00211 
00212                 //indices.push_back(face.mIndices[j]);
00213                 indices.push_back(mesh->mFaces[i].mIndices[j]);
00214 
00215             }
00216         }
00217         // process material
00218         if (mesh->mMaterialIndex >= 0)
00219         {
00220             //[...]
00221             if (mesh->mMaterialIndex >= 0)
00222             {
00223                 aiMaterial* material = scene->mMaterials[mesh->mMaterialIndex];
00224                 vector<Texture> diffuseMaps = loadMaterialTextures(material,
00225                     aiTextureType_DIFFUSE, "texture_diffuse");
00226                 textures.insert(textures.end(), diffuseMaps.begin(), diffuseMaps.end());
00227                 vector<Texture> specularMaps = loadMaterialTextures(material,
00228                     aiTextureType_SPECULAR, "texture_specular");
00229                 textures.insert(textures.end(), specularMaps.begin(),
00230                     specularMaps.end());
00231             }
00232         }
00233         //TrPrE(ctx);
00234         return Mesh(vertices, indices, textures);
00235     }
