00237      vector<Texture> Model::loadMaterialTextures(aiMaterial* mat, aiTextureType type, string typeName)
00238     {
00239         //TrPr(ctx, __func__)
00240         vector<Texture> textures;
00241         for (unsigned int i = 0; i < mat->GetTextureCount(type); i++)
00242         {
00243             aiString str;
00244             mat->GetTexture(type, i, &str);
00245             bool skip = false;
00246             for (unsigned int j = 0; j < textures_loaded.size(); j++)
00247             {
00248                 if (std::strcmp(textures_loaded[j].path.data(),
00249                     str.C_Str()) == 0)
00250                 {
00251                     textures.push_back(textures_loaded[j]);
00252                     skip = true;
00253                     break;
00254                 }
00255             }
00256             if (!skip)
00257             { // if texture hasn’t been loaded already, load it
00258                 Texture texture;
00259                 texture.id = TextureFromFile(str.C_Str(), directory, true);
00260                 texture.type = typeName;
00261                 texture.path = str.C_Str();
00262                 textures.push_back(texture);
00263                 textures_loaded.push_back(texture); // add to loaded textures
00264             }
00265         }
00266         //TrPrE(ctx);
00267         return textures;
00268     }
