00270      unsigned int Model::TextureFromFile(const char* path, const string& directory, bool gamma)
00271     {
00272         //TrPr(ctx, __func__)
00273         string filename = string(path);
00274         filename = directory + '\\' + filename;
00275 
00276         unsigned int textureID;
00277         glGenTextures(1, &textureID);
00278 
00279         int width, height, nrComponents;
00280         unsigned char* data = stbi_load(filename.c_str(), &width, &height, &nrComponents, 0);
00281         if (data)
00282         {
00283             GLenum format;
00284             if (nrComponents == 1)
00285                 format = GL_RED;
00286             else if (nrComponents == 3)
00287                 format = GL_RGB;
00288             else if (nrComponents == 4)
00289                 format = GL_RGBA;
00290 
00291             glBindTexture(GL_TEXTURE_2D, textureID);
00292             glTexImage2D(GL_TEXTURE_2D, 0, format, width, height, 0, format, GL_UNSIGNED_BYTE, data);
00293             glGenerateMipmap(GL_TEXTURE_2D);
00294 
00295             glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
00296             glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
00297             glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR_MIPMAP_LINEAR);
00298             glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
00299 
00300             stbi_image_free(data);
00301         }
00302         else
00303         {
00304             std::cout << "Texture failed to load at path: " << path << std::endl;
00305             stbi_image_free(data);
00306         }
00307         //TrPrE(ctx);
00308         return textureID;
00309     }
